import{_ as a,p as n,q as s,Y as e}from"./framework-e1bed10d.js";const t="/my-blog/assets/thread-state-and-method-0abc6fdd.png",p={},i=e(`<h1 id="线程状态" tabindex="-1"><a class="header-anchor" href="#线程状态" aria-hidden="true">#</a> 线程状态</h1><p>操作系统的线程主要有以下三个状态：</p><ul><li>绪状态(ready)：线程正在等待使用 CPU，经调度程序调用之后进入 running 状态。</li><li>执行状态(running)：线程正在使用 CPU。</li><li>等待状态(waiting): 线程经过等待事件的调用或者正在等待其他资源（如 I/O）</li></ul><h2 id="new" tabindex="-1"><a class="header-anchor" href="#new" aria-hidden="true">#</a> NEW</h2><p>处于NEW状态的线程此时尚未启动。这里的尚未启动指的是还没调用Thread实例的start()方法</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">private</span> <span class="token keyword">void</span> <span class="token function">testStateNew</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">Thread</span> thread <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Thread</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>thread<span class="token punctuation">.</span><span class="token function">getState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 输出 NEW</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在调用start之后，threadStatus的值会改变（threadStatus !=0），再次调用start方法会抛出IllegalThreadStateException异常</p><p>假如一个线程执行完毕，threadStatus为2代表当前线程状态为TERMINATED，不能再调用start方法</p><h2 id="runnable" tabindex="-1"><a class="header-anchor" href="#runnable" aria-hidden="true">#</a> RUNNABLE</h2><p>表示当前线程正在运行中，处于RUNNABLE状态的线程在Java虚拟机中运行，也有可能在等待CPU分配资源</p><p>Java线程的RUNNABLE状态其实包括了操作系统线程的ready和running两个状态</p><h2 id="blocked" tabindex="-1"><a class="header-anchor" href="#blocked" aria-hidden="true">#</a> BLOCKED</h2><p>阻塞状态，处于BLOCKED状态的线程正等待锁的释放以进入同步区</p><h2 id="waiting" tabindex="-1"><a class="header-anchor" href="#waiting" aria-hidden="true">#</a> WAITING</h2><p>等待状态，处于等待状态的线程变成RUNNABLE状态需要其他线程唤醒</p><h2 id="timed-waiting" tabindex="-1"><a class="header-anchor" href="#timed-waiting" aria-hidden="true">#</a> TIMED_WAITING</h2><p>超时等待状态，线程等待一个具体的时间，时间到后会被自动唤醒</p><h2 id="terminated" tabindex="-1"><a class="header-anchor" href="#terminated" aria-hidden="true">#</a> TERMINATED</h2><p>终止状态，此时线程已执行完毕</p><h2 id="线程状态的转换" tabindex="-1"><a class="header-anchor" href="#线程状态的转换" aria-hidden="true">#</a> 线程状态的转换</h2><p>线程状态转换图</p><p><img src="`+t+'" alt="线程状态转换图"></p><h2 id="线程中断" tabindex="-1"><a class="header-anchor" href="#线程中断" aria-hidden="true">#</a> 线程中断</h2><p>在某些情况下，我们在线程启动后发现并不需要它继续执行下去时，需要中断线程。目前在 Java 里还没有安全方法来直接停止线程，但是 Java 提供了线程中断机制来处理需要中断线程的情况。</p><p>线程中断机制是一种协作机制。需要注意，通过中断操作并不能直接终止一个线程，而是通知需要被中断的线程自行处理。</p><p>Thread类里提供的关于线程中断的几个方法：</p><ul><li>Thread.interrupt()：中断线程。这里的中断线程并不会立即停止线程，而是设置线程的中断状态为true（默认是false）</li><li>Thread.isInterrupted()：测试当前线程是否被中断</li><li>Thread.interrupted()：检测当前线程是否被中断，与 isInterrupted() 方法不同的是，这个方法如果发现当前线程被中断，会清除线程的中断状态</li></ul><p>在线程中断机制里，当其他线程通知需要被中断的线程后，线程中断的状态被设置为 true，但是具体被要求中断的线程要怎么处理，完全由被中断线程自己决定，可以在合适的时机中断请求，也可以完全不处理继续执行下去</p>',28),r=[i];function c(d,o){return n(),s("div",null,r)}const u=a(p,[["render",c],["__file","status.html.vue"]]);export{u as default};
